    <div class="ac-user-picker"><label for="ac-member"><?php echo e(t('Select user','ইউজার নির্বাচন')); ?></label><div class="ac-select-wrap"><svg class="ac-ico"><use href="#ac-i-user"/></svg><select id="ac-member" class="ac-select"><option value=""><?php echo e(t('Choose a user','ইউজার বেছে নিন')); ?></option><?php $__currentLoopData = $members; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $member): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($member->id); ?>" <?php echo e(!$member->can_manage ? 'disabled' : ''); ?>><?php echo e($member->name); ?> <?php if($member->email): ?>— <?php echo e($member->email); ?><?php endif; ?><?php echo e(!$member->can_manage ? ' (Protected)' : ''); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div id="ac-selected-person"></div></div>
    <div class="ac-stat"><span class="ac-stat-icon ac-violet"><svg class="ac-ico"><use href="#ac-i-layers"/></svg></span><div><strong id="ac-stat-modules">0</strong><small><?php echo e(t('Modules','মডিউল')); ?></small></div></div>
    <div class="ac-stat"><span class="ac-stat-icon ac-sky"><svg class="ac-ico"><use href="#ac-i-list"/></svg></span><div><strong id="ac-stat-records">0</strong><small><?php echo e(t('Access points','অ্যাক্সেস পয়েন্ট')); ?></small></div></div>
    <div class="ac-stat"><span class="ac-stat-icon ac-green"><svg class="ac-ico"><use href="#ac-i-check"/></svg></span><div><strong id="ac-stat-crud">0/0</strong><small><?php echo e(t('CRUD granted','CRUD অনুমতি')); ?></small></div></div>
    <div class="ac-stat"><span class="ac-stat-icon ac-purple"><svg class="ac-ico"><use href="#ac-i-lock"/></svg></span><div><strong id="ac-stat-extra">0</strong><small><?php echo e(t('Extra granted','অতিরিক্ত অনুমতি')); ?></small></div></div>
</section>
<section class="ac-panel" id="ac-workspace">
    <div class="ac-empty"><div class="ac-empty-icon"><svg class="ac-ico" style="width:30px;height:30px"><use href="#ac-i-shield"/></svg></div><h3><?php echo e(t('Select a user to get started','শুরু করতে একজন ইউজার নির্বাচন করুন')); ?></h3><p><?php echo e(t('Choose a user from the selector above. Their assigned modules, menus, child menus and extra permissions will appear here.','উপরের তালিকা থেকে ইউজার বেছে নিলে তার মডিউল, মেনু, চাইল্ড মেনু ও অতিরিক্ত পারমিশন দেখা যাবে।')); ?></p></div>
</section>
<div class="ac-footer" id="ac-footer" hidden><span><?php echo e(t('Changes remain local until you click Save changes.','Save changes না করা পর্যন্ত পরিবর্তন সংরক্ষিত হবে না।')); ?></span><strong id="ac-footer-state"></strong></div>
</div></main></div>
<?php $__env->stopSection(); ?>
<?php $__env->startPush('scripts'); ?>
<?php
    $acStrings=[
        'saved'=>t('All changes saved','সব পরিবর্তন সংরক্ষিত'),'pending'=>t('Unsaved changes','অসংরক্ষিত পরিবর্তন'),
        'structure'=>t('Permission structure','পারমিশন স্ট্রাকচার'),'hint'=>t('Grant access at module level or fine-tune each menu and child menu.','মডিউল, মেনু ও চাইল্ড মেনু অনুযায়ী অনুমতি দিন।'),
        'search'=>t('Search module or menu...','মডিউল বা মেনু খুঁজুন...'),'expand'=>t('Expand all','সব খুলুন'),'collapse'=>t('Collapse all','সব বন্ধ করুন'),
        'legend'=>t('PERMISSION LEGEND','পারমিশন পরিচিতি'),'view'=>t('View','দেখুন'),'create'=>t('Create','তৈরি'),'update'=>t('Update','আপডেট'),'delete'=>t('Delete','ডিলিট'),
        'extra'=>t('Extra permissions','অতিরিক্ত পারমিশন'),'menus'=>t('menus','মেনু'),'childMenus'=>t('child menus','চাইল্ড মেনু'),
        'crudEnabled'=>t('CRUD permissions enabled','CRUD অনুমতি চালু'),'full'=>t('Full access','সম্পূর্ণ অ্যাক্সেস'),
        'grantModule'=>t('Grant full module access','মডিউলের সব অনুমতি দিন'),'removeModule'=>t('Remove module access','মডিউলের অনুমতি বাতিল'),
        'grantMenu'=>t('Grant menu access','মেনুর সব অনুমতি দিন'),'removeMenu'=>t('Remove menu access','মেনুর অনুমতি বাতিল'),
        'grantAll'=>t('Grant all','সব দিন'),'clearAll'=>t('Clear all','সব বাতিল'),'extraEnabled'=>t('enabled','সক্রিয়'),
        'noMatches'=>t('No matching access items found.','মিলযুক্ত কিছু পাওয়া যায়নি।'),'noModules'=>t('No active modules found.','কোনো মডিউল পাওয়া যায়নি।'),
        'loading'=>t('Loading access permissions...','পারমিশন লোড হচ্ছে...'),'savedSuccess'=>t('Permissions saved successfully.','পারমিশন সফলভাবে সংরক্ষিত হয়েছে।'),
        'discarded'=>t('Unsaved changes discarded.','অসংরক্ষিত পরিবর্তন বাতিল হয়েছে।'),'failed'=>t('Unable to process your request.','অনুরোধ সম্পন্ন করা যায়নি।'),
        'confirm'=>t('Discard your unsaved changes?','অসংরক্ষিত পরিবর্তন বাতিল করবেন?'),'pendingFooter'=>t('You have pending changes.','আপনার অসংরক্ষিত পরিবর্তন আছে।'),
        'savedFooter'=>t('Everything is up to date.','সবকিছু আপডেট আছে।'),'saving'=>t('Saving...','সংরক্ষণ হচ্ছে...'),
        'removeExtras'=>t('Remove all','সব বাতিল'),'grantExtras'=>t('Grant all','সব দিন')
    ];
