<script>
document.addEventListener('DOMContentLoaded',function(){
    const members=<?php echo json_encode($members, 15, 512) ?>;
    const strings=<?php echo json_encode($acStrings, 15, 512) ?>;
    const getUrl=<?php echo json_encode(route('authorization.access-control'), 15, 512) ?>;
    const saveUrl=<?php echo json_encode(route('authorization.access-control.store'), 15, 512) ?>;
    const csrf=document.querySelector('meta[name="csrf-token"]')?.content||<?php echo json_encode(csrf_token(), 15, 512) ?>;
    const $=id=>document.getElementById(id);
    const fields=['can_view','can_create','can_update','can_delete'];
    const fieldLabels=[strings.view,strings.create,strings.update,strings.delete];
    const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const ico=(name,style='')=>`<svg class="ac-ico" ${style}><use href="#ac-i-${name}"/></svg>`;
    const lang=localStorage.getItem('nexabiz-language')||'en';
    const name=x=>lang==='bn'&&x.name_bn?x.name_bn:x.name;
    let selected=null,modules=[],snapshot='',busy=false,term='',expandedModules=new Set(),expandedMenus=new Set();
    const records=m=>m.menus.flatMap(menu=>menu.child_menus.length?menu.child_menus.map(c=>c.permission):menu.permission?[menu.permission]:[]);
    const count=p=>fields.reduce((n,k)=>n+Number(!!p?.[k]),0);
    const extraItems=m=>[...m.extra_permissions,...m.menus.flatMap(n=>[...n.extra_permissions,...n.child_menus.flatMap(c=>c.extra_permissions)])];
    const moduleStats=m=>{const rows=records(m);return {granted:rows.reduce((n,p)=>n+count(p),0),possible:rows.length*4,records:rows.length,extra:extraItems(m).filter(p=>p.allowed).length};};
    const isDirty=()=>selected!==null&&JSON.stringify(modules)!==snapshot;
    const allOn=p=>count(p)===4;
    const leafMenu=m=>m.child_menus.length?m.child_menus.map(c=>c.permission):m.permission?[m.permission]:[];
    const setAll=(p,v)=>{if(p)fields.forEach(k=>p[k]=v);};
    function alertBox(message,error=false){const node=$('ac-notice');node.hidden=false;node.className='ac-notice'+(error?' error':'');node.innerHTML=`<span>${html(message)}</span><button type="button" class="ac-chevron" data-action="dismiss" aria-label="Close">×</button>`;}
    function status(){const ready=selected!==null&&!busy,dirty=isDirty();$('ac-undo').disabled=!ready||!dirty;$('ac-reload').disabled=!ready;$('ac-save').disabled=!ready||!dirty;$('ac-save').querySelector('span').textContent=busy?strings.saving:'<?php echo e(t('Save changes','সংরক্ষণ করুন')); ?>';$('ac-footer').hidden=!ready;$('ac-footer-state').textContent=dirty?strings.pendingFooter:strings.savedFooter;}
    function stats(){let total={granted:0,possible:0,records:0,extra:0};modules.forEach(m=>{const a=moduleStats(m);Object.keys(total).forEach(k=>total[k]+=a[k]);});$('ac-stat-modules').textContent=modules.length;$('ac-stat-records').textContent=total.records;$('ac-stat-crud').textContent=total.granted+'/'+total.possible;$('ac-stat-extra').textContent=total.extra;status();}
    function extras(items,mi,ni=-1,ci=-1){if(!items.length)return '';let enabled=items.filter(x=>x.allowed).length;return `<section class="ac-extra"><div class="ac-extra-head"><div style="display:flex;align-items:center;gap:8px">${ico('lock')}<strong>${html(strings.extra)}</strong><span class="ac-tag ac-tag-muted">${enabled}/${items.length} ${html(strings.extraEnabled)}</span></div><button class="ac-btn ac-btn-sm" type="button" data-action="extra-all" data-m="${mi}" data-n="${ni}" data-c="${ci}">${html(enabled===items.length?strings.removeExtras:strings.grantExtras)}</button></div><div class="ac-extra-grid">${items.map((p,i)=>`<label title="${html(p.description||p.key)}" class="ac-extra-item ${p.allowed?'is-on':''}"><input type="checkbox" data-action="extra" data-m="${mi}" data-n="${ni}" data-c="${ci}" data-i="${i}" ${p.allowed?'checked':''}/><span><strong>${html(p.name)}</strong><small>${html(p.key)}</small>${p.description?`<small>${html(p.description)}</small>`:''}</span></label>`).join('')}</div></section>`;}
    function crud(permission,mi,ni,ci){const full=allOn(permission);return `<div class="ac-crud">${fields.map((k,i)=>`<label class="ac-crud-check ${permission?.[k]?'is-on':''}"><input type="checkbox" data-action="crud" data-m="${mi}" data-n="${ni}" data-c="${ci}" data-field="${k}" ${permission?.[k]?'checked':''}/>${html(fieldLabels[i])}</label>`).join('')}<button type="button" class="ac-btn ac-btn-sm ${full?'ac-btn-danger':'ac-btn-primary'}" data-action="row-all" data-m="${mi}" data-n="${ni}" data-c="${ci}">${html(full?strings.clearAll:strings.grantAll)}</button></div>`;}
    function childView(c,mi,ni,ci){return `<div class="ac-child"><div class="ac-child-main"><div class="ac-child-name"><span class="ac-menu-icon">${ico('list')}</span><span><strong class="ac-menu-name">${html(name(c))}</strong><small class="ac-menu-count">${count(c.permission)}/4 ${html(strings.crudEnabled)}</small></span></div>${crud(c.permission,mi,ni,ci)}</div>${extras(c.extra_permissions,mi,ni,ci)}</div>`;}
    function menuView(m,mi,ni,searchMode){const hasChildren=m.child_menus.length>0,opened=searchMode||expandedMenus.has(m.id),leaves=leafMenu(m),granted=leaves.reduce((n,p)=>n+count(p),0),possible=leaves.length*4,full=possible>0&&granted===possible;const childMatches=m.child_menus.filter(c=>!term||String(name(c)+' '+c.code).toLowerCase().includes(term));const match=!term||String(name(m)+' '+m.code).toLowerCase().includes(term),parentMatch=!term||String(name(modules[mi])+' '+modules[mi].code).toLowerCase().includes(term);if(term&&!match&&!parentMatch&&!childMatches.length)return '';const displayChildren=match||parentMatch?m.child_menus:childMatches;return `<div class="ac-menu"><div class="ac-menu-head"><div class="ac-menu-info">${hasChildren?`<button class="ac-chevron" type="button" data-action="toggle-menu" data-id="${m.id}">${ico(opened?'down':'right')}</button>`:`<span style="width:27px"></span>`}<span class="ac-menu-icon">${ico('menu')}</span><span><strong class="ac-menu-name">${html(name(m))}</strong>${hasChildren?`<span class="ac-tag ac-tag-muted" style="margin-left:7px">${m.child_menus.length} ${html(strings.childMenus)}</span>`:''}<small class="ac-menu-count">${granted}/${possible} ${html(strings.crudEnabled)}</small></span></div>${hasChildren?`<button type="button" class="ac-btn ac-btn-sm ${full?'ac-btn-danger':'ac-btn-sky'}" data-action="menu-all" data-m="${mi}" data-n="${ni}">${html(full?strings.removeMenu:strings.grantMenu)}</button>`:crud(m.permission,mi,ni,-1)}</div>${extras(m.extra_permissions,mi,ni)}${hasChildren&&opened?`<div class="ac-child-list">${displayChildren.map(c=>childView(c,mi,ni,m.child_menus.indexOf(c))).join('')}</div>`:''}</div>`;}
    function moduleView(m,mi,searchMode){const match=!term||String(name(m)+' '+m.code).toLowerCase().includes(term);const menus=m.menus.map((menu,ni)=>menuView(menu,mi,ni,searchMode||!!term)).filter(Boolean);if(!match&&!menus.length)return '';const s=moduleStats(m),full=s.possible>0&&s.granted===s.possible,opened=searchMode||expandedModules.has(m.id);return `<article class="ac-module"><div class="ac-module-head"><button class="ac-title-button" data-action="toggle-module" data-id="${m.id}" type="button"><span class="ac-title-icon">${ico('layers')}</span><span class="ac-title-text"><strong>${html(name(m))}<span class="ac-tag ac-tag-muted" style="margin-left:7px">${m.menus.length} ${html(strings.menus)}</span>${full?`<span class="ac-tag ac-tag-ok" style="margin-left:6px">${html(strings.full)}</span>`:''}</strong><span class="ac-title-sub">${s.granted} / ${s.possible} ${html(strings.crudEnabled)}${s.extra?' · '+s.extra+' '+html(strings.extraEnabled):''}</span></span>${ico(opened?'down':'right')}</button><div class="ac-actions"><div class="ac-progress"><span style="width:${s.possible?100*s.granted/s.possible:0}%"></span></div><button type="button" class="ac-btn ac-btn-sm ${full?'ac-btn-danger':'ac-btn-primary'}" data-action="module-all" data-m="${mi}">${html(full?strings.removeModule:strings.grantModule)}</button></div></div>${opened?`<div class="ac-module-body">${extras(m.extra_permissions,mi)}${menus.join('')||`<p class="ac-hint">${html(strings.noModules)}</p>`}</div>`:''}</article>`;}
    function render(){stats();if(selected===null){return;}const badge=isDirty()?`<span class="ac-tag ac-tag-warn">${html(strings.pending)}</span>`:`<span class="ac-tag ac-tag-ok">${html(strings.saved)}</span>`;const toolbar=`<div class="ac-permission-head"><div class="ac-permission-toolbar"><div><div class="ac-headline"><h2>${html(strings.structure)}</h2><span id="ac-dirty-badge">${badge}</span></div><p class="ac-hint">${html(strings.hint)}</p></div><div class="ac-actions"><div class="ac-search">${ico('list')}<input id="ac-search" type="search" value="${html(term)}" placeholder="${html(strings.search)}"/></div><button type="button" class="ac-btn ac-btn-sm" data-action="expand">${html(strings.expand)}</button><button type="button" class="ac-btn ac-btn-sm" data-action="collapse">${html(strings.collapse)}</button></div></div><div class="ac-legend"><strong>${html(strings.legend)}</strong>${fieldLabels.map((v,i)=>`<span><span class="ac-key">${'VCUD'[i]}</span>${html(v)}</span>`).join('')}<span style="margin-left:auto;color:#7c3aed">${ico('lock')} ${html(strings.extra)}</span></div></div>`;const blocks=modules.map((m,i)=>moduleView(m,i,!!term)).filter(Boolean).join('');$('ac-workspace').innerHTML=toolbar+(blocks?`<div class="ac-tree">${blocks}</div>`:`<div class="ac-empty"><h3>${html(term?strings.noMatches:strings.noModules)}</h3></div>`);}
    async function load(id){busy=true;selected=Number(id);term='';modules=[];snapshot='';expandedModules.clear();expandedMenus.clear();$('ac-notice').hidden=true;$('ac-workspace').innerHTML=`<div class="ac-empty"><div class="ac-empty-icon">${ico('refresh')}</div><h3>${html(strings.loading)}</h3></div>`;status();try{const res=await fetch(getUrl+'/'+selected,{headers:{Accept:'application/json'},credentials:'same-origin'});const json=await res.json();if(!res.ok)throw Error(json.message||strings.failed);modules=json.data.modules||[];snapshot=JSON.stringify(modules);modules.forEach(m=>expandedModules.add(m.id));render();}catch(err){alertBox(err.message||strings.failed,true);modules=[];snapshot=JSON.stringify(modules);render();}finally{busy=false;status();}}
    $('ac-member').addEventListener('change',function(){const id=this.value?Number(this.value):null;if(isDirty()&&!confirm(strings.confirm)){this.value=String(selected);return;}selected=id;const member=members.find(m=>Number(m.id)===id);$('ac-selected-person').innerHTML=member?`<div class="ac-user-summary"><span class="ac-avatar">${html(member.name.slice(0,1).toUpperCase())}</span><span><strong>${html(member.name)}</strong><small>${html(member.email||'User ID: '+member.id)}</small></span></div>`:'';if(id)load(id);else{modules=[];snapshot='';$('ac-workspace').innerHTML=`<div class="ac-empty"><div class="ac-empty-icon">${ico('shield')}</div><h3><?php echo e(t('Select a user to get started','শুরু করতে একজন ইউজার নির্বাচন করুন')); ?></h3></div>`;stats();}});
    $('ac-workspace').addEventListener('click',function(event){const btn=event.target.closest('button[data-action]');if(!btn||busy)return;const action=btn.dataset.action,mi=Number(btn.dataset.m),ni=Number(btn.dataset.n),ci=Number(btn.dataset.c);if(action==='expand'){modules.forEach(m=>{expandedModules.add(m.id);m.menus.forEach(n=>expandedMenus.add(n.id));});render();}if(action==='collapse'){expandedModules.clear();expandedMenus.clear();render();}if(action==='toggle-module'){const id=Number(btn.dataset.id);expandedModules.has(id)?expandedModules.delete(id):expandedModules.add(id);render();}if(action==='toggle-menu'){const id=Number(btn.dataset.id);expandedMenus.has(id)?expandedMenus.delete(id):expandedMenus.add(id);render();}if(action==='module-all'){const m=modules[mi],s=moduleStats(m),v=!(s.possible>0&&s.granted===s.possible);m.menus.forEach(menu=>leafMenu(menu).forEach(p=>setAll(p,v)));render();}if(action==='menu-all'){const menu=modules[mi].menus[ni],rows=leafMenu(menu),v=!rows.every(allOn);rows.forEach(p=>setAll(p,v));render();}if(action==='row-all'){const menu=modules[mi].menus[ni],p=ci<0?menu.permission:menu.child_menus[ci].permission;setAll(p,!allOn(p));render();}if(action==='extra-all'){const items=ci>=0?modules[mi].menus[ni].child_menus[ci].extra_permissions:ni>=0?modules[mi].menus[ni].extra_permissions:modules[mi].extra_permissions;const v=!items.every(p=>p.allowed);items.forEach(p=>p.allowed=v);render();}});
    $('ac-workspace').addEventListener('change',function(event){const el=event.target;if(busy)return;if(el.id==='ac-search')return;const mi=Number(el.dataset.m),ni=Number(el.dataset.n),ci=Number(el.dataset.c);if(el.dataset.action==='crud'){const p=ci<0?modules[mi].menus[ni].permission:modules[mi].menus[ni].child_menus[ci].permission;p[el.dataset.field]=el.checked;if(el.dataset.field==='can_view'&&!el.checked){p.can_create=false;p.can_update=false;p.can_delete=false;}if(el.dataset.field!=='can_view'&&el.checked)p.can_view=true;render();}if(el.dataset.action==='extra'){const items=ci>=0?modules[mi].menus[ni].child_menus[ci].extra_permissions:ni>=0?modules[mi].menus[ni].extra_permissions:modules[mi].extra_permissions;items[Number(el.dataset.i)].allowed=el.checked;render();}});
    $('ac-workspace').addEventListener('input',function(event){if(event.target.id!=='ac-search')return;const node=event.target;const start=node.selectionStart;term=node.value.trim().toLowerCase();render();const newNode=$('ac-search');newNode?.focus();try{newNode?.setSelectionRange(start,start)}catch(e){}});
    $('ac-undo').addEventListener('click',()=>{modules=JSON.parse(snapshot);$('ac-notice').hidden=true;alertBox(strings.discarded);render();});
    $('ac-reload').addEventListener('click',()=>{if(isDirty()&&!confirm(strings.confirm))return;if(selected)load(selected);});
    $('ac-save').addEventListener('click',async()=>{if(!selected||!isDirty()||busy)return;busy=true;status();const permissions=[];const extraPermissions=[];modules.forEach(m=>{extraPermissions.push(...m.extra_permissions.filter(x=>x.allowed).map(x=>x.id));m.menus.forEach(menu=>{extraPermissions.push(...menu.extra_permissions.filter(x=>x.allowed).map(x=>x.id));if(menu.child_menus.length)menu.child_menus.forEach(c=>{permissions.push({module_id:m.id,menu_id:menu.id,child_menu_id:c.id,...c.permission});extraPermissions.push(...c.extra_permissions.filter(x=>x.allowed).map(x=>x.id));});else if(menu.permission)permissions.push({module_id:m.id,menu_id:menu.id,child_menu_id:null,...menu.permission});});});try{const res=await fetch(saveUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({member_id:selected,permissions,extra_permissions:[...new Set(extraPermissions)]})});const data=await res.json();if(!res.ok)throw Error(data.message||Object.values(data.errors||{}).flat()[0]||strings.failed);snapshot=JSON.stringify(modules);alertBox(data.message||strings.savedSuccess);render();}catch(error){alertBox(error.message||strings.failed,true);}finally{busy=false;status();}});
    $('ac-notice').addEventListener('click',e=>{if(e.target.closest('[data-action="dismiss"]'))$('ac-notice').hidden=true;});
    document.querySelectorAll('[data-ws-sidebar-toggle],[data-ws-sidebar-overlay]').forEach(el=>el.addEventListener('click',()=>document.body.classList.toggle('ws-sidebar-open')));
    document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('ws-sidebar-open');});
    document.querySelectorAll('.workspace-sidebar a').forEach(el=>el.addEventListener('click',()=>document.body.classList.remove('ws-sidebar-open')));
    window.addEventListener('beforeunload',e=>{if(isDirty()){e.preventDefault();e.returnValue='';}});
    status();
});
</script>
